+      { name: "shell", detail: "node dist/cli/main.js digest" },
+      { name: "read", detail: "a.ts" },
+      { name: "glob", detail: "**/dist/**" },
+      { name: "custom_tool" },
+    ]);
+  });
+
+  it("counts one step per model call plus the final answer", () => {
+    assert.equal(parseCursorStreamJson(lines.join("\n")).steps, 4);
+  });
